class Solution {
public:
    int halveArray(vector<int>& nums) {
        priority_queue<double> pq;
        double sumVal = 0.0;
        for (int x : nums) {
            pq.push((double)x);
            sumVal += x;
        }
        double target = sumVal / 2.0;
        double reduced = 0.0;
        int ops = 0;
        while (reduced < target) {
            double top = pq.top();
            pq.pop();
            double half = top / 2.0;
            reduced += half;
            pq.push(half);
            ops++;
        }
        return ops;
    }
};

class Solution {
    public int halveArray(int[] nums) {
        PriorityQueue<Double> pq = new PriorityQueue<>(Collections.reverseOrder());
        double sumVal = 0.0;
        for (int x : nums) {
            pq.add((double) x);
            sumVal += x;
        }
        double target = sumVal / 2.0;
        double reduced = 0.0;
        int ops = 0;
        while (reduced < target) {
            double top = pq.poll();
            double half = top / 2.0;
            reduced += half;
            pq.add(half);
            ops++;
        }
        return ops;
    }
}

