var halveArray = function(nums) {
    // Simple binary heap implementation
    const heap = [];
    const push = (val) => {
        heap.push(val);
        let idx = heap.length - 1;
        while (idx > 0) {
            const p = Math.floor((idx - 1) / 2);
            if (heap[p] < heap[idx]) {
                const tmp = heap[p];
                heap[p] = heap[idx];
                heap[idx] = tmp;
                idx = p;
            } else break;
        }
    };
    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length > 0) {
            heap[0] = last;
            let idx = 0;
            while (true) {
                let left = 2 * idx + 1, right = 2 * idx + 2, best = idx;
                if (left < heap.length && heap[left] > heap[best]) best = left;
                if (right < heap.length && heap[right] > heap[best]) best = right;
                if (best !== idx) {
                    const tmp = heap[idx];
                    heap[idx] = heap[best];
                    heap[best] = tmp;
                    idx = best;
                } else break;
            }
        }
        return top;
    };

    let total = 0;
    for (const x of nums) {
        total += x;
        push(x);
    }
    const target = total / 2;
    let reduced = 0;
    let ops = 0;
    while (reduced < target) {
        const top = pop();
        const half = top / 2;
        reduced += half;
        push(half);
        ops++;
    }
    return ops;
};
